script:
(function () {
  'use strict';
  // Repayment calculator: a balance repaid p times a year, interest compounding m times a year.
  //   Rate per payment: i = (1 + r/m)^(m/p) - 1 (continuous: e^(r/p) - 1).
  //   Target date: n = payments from the first payment date to the target month, inclusive
  //     (n = floor(monthsBetween * p / 12) + 1); payment = B * i / (1 - (1 + i)^-n), B / n at 0%.
  //   Fixed payment: simulate period by period; the final payment clears the balance. The payment must
  //     exceed one period's interest B * i.
  //   Payment dates: monthly-based schedules add 12/p months per payment (twice a month adds half a
  //     month, i.e. the 1st and 15th); weekly and every-two-weeks schedules add 7 or 14 days.
  // Verified in Node (scratchpad w3loans/tests): $10,000 at 10% monthly over 60 payments = $212.47,
  //   total $12,748.23 (closed form; matches a published calculator's default result); $10,000 at 10%
  //   paying $212.48 a month takes 60 payments ($212.47 leaves a few cents for a 61st); first payment Oct 2026 with target Sep 2031 = 60 monthly
  //   payments; 0% divides evenly; biweekly with monthly compounding uses i = (1 + 0.10/12)^(12/26) - 1;
  //   blank, negative, past target date and too-small payment show an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  var NAMES = { 12: 'monthly', 24: 'twice-monthly', 26: 'every-two-weeks', 52: 'weekly', 4: 'quarterly' };
  var MAX_YEARS = 100;
  var last = null;

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function mode() {
    var r = document.querySelector('input[name="rpMode"]:checked');
    return r ? r.value : 'date';
  }

  function periodicRate(annualRate, compound, perYear) {
    if (annualRate === 0) return 0;
    if (compound === 0) return Math.exp(annualRate / perYear) - 1;
    return Math.pow(1 + annualRate / compound, compound / perYear) - 1;
  }

  function payment(principal, i, n) {
    if (n <= 0 || principal <= 0) return 0;
    if (i === 0) return principal / n;
    return principal * i / (1 - Math.pow(1 + i, -n));
  }

  function simulate(loan, i, pay, maxN) {
    var bal = loan, rows = [], totalInterest = 0, totalPaid = 0;
    for (var k = 1; k <= maxN && bal > 0.005; k++) {
      var interest = bal * i;
      var amount = Math.min(pay, bal + interest);
      bal = bal + interest - amount;
      if (bal < 0.005) bal = 0;
      totalInterest += interest;
      totalPaid += amount;
      rows.push({ n: k, amount: amount, interest: interest, principal: amount - interest, balance: bal });
    }
    return { rows: rows, totalInterest: totalInterest, totalPaid: totalPaid, balance: bal };
  }

  // Date of payment number k (1-based) given the first payment's year and month (0-11), day 1.
  function paymentDate(year, month, perYear, k) {
    var idx = k - 1;
    if (perYear === 52 || perYear === 26) return new Date(year, month, 1 + idx * (perYear === 52 ? 7 : 14));
    if (perYear === 24) return new Date(year, month + Math.floor(idx / 2), idx % 2 ? 15 : 1);
    return new Date(year, month + idx * 12 / perYear, 1);
  }

  function monthYear(d) { return MONTHS[d.getMonth()] + ' ' + d.getFullYear(); }

  function duration(months) {
    months = Math.round(months);
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function cell(tr, text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); }

  function headRow(labels) {
    var head = el('rpScheduleHead');
    head.textContent = '';
    var tr = document.createElement('tr');
    labels.forEach(function (t) { var th = document.createElement('th'); th.scope = 'col'; th.textContent = t; tr.appendChild(th); });
    head.appendChild(tr);
  }

  function clearResults() {
    ['rpMain', 'rpPayoff', 'rpInterest', 'rpTotal', 'rpCount', 'rpTime', 'rpFinal', 'rpSummary'].forEach(function (id) { setText(id, '–'); });
    el('rpSchedule').textContent = '';
    last = null;
  }

  function renderSchedule() {
    var body = el('rpSchedule');
    body.textContent = '';
    if (!last) return;
    if (el('rpView').value === 'period') {
      headRow(['#', 'Date', 'Payment', 'Principal', 'Interest', 'Balance']);
      last.rows.forEach(function (row) {
        var tr = document.createElement('tr');
        cell(tr, String(row.n)); cell(tr, last.dateOf(row.n).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }));
        cell(tr, money.format(row.amount)); cell(tr, money.format(row.principal)); cell(tr, money.format(row.interest));
        cell(tr, money.format(row.balance));
        body.appendChild(tr);
      });
    } else {
      headRow(['Year', 'Payments', 'Principal', 'Interest', 'Ending balance']);
      var count = 0, p = 0, intr = 0;
      last.rows.forEach(function (row, idx) {
        count++; p += row.principal; intr += row.interest;
        var yr = last.dateOf(row.n).getFullYear();
        var next = idx < last.rows.length - 1 ? last.dateOf(row.n + 1).getFullYear() : null;
        if (next !== yr) {
          var tr = document.createElement('tr');
          cell(tr, String(yr)); cell(tr, String(count)); cell(tr, money.format(p)); cell(tr, money.format(intr));
          cell(tr, money.format(row.balance));
          body.appendChild(tr);
          count = 0; p = 0; intr = 0;
        }
      });
    }
  }

  function update() {
    var m = mode();
    el('rpDateField').hidden = m !== 'date';
    el('rpPayField').hidden = m !== 'payment';
    var balance = read('rpBalance'), rate = read('rpRate'), pay = read('rpPay'),
        perYear = parseInt(el('rpFreq').value, 10), compound = parseInt(el('rpCompound').value, 10),
        startMonth = parseInt(el('rpStartMonth').value, 10), startYear = read('rpStartYear'),
        endMonth = parseInt(el('rpEndMonth').value, 10), endYear = read('rpEndYear'), msg = '';
    if (isNaN(balance) || balance <= 0) msg = 'Enter a balance greater than $0.';
    else if (isNaN(rate) || rate < 0 || rate > 100) msg = 'Enter an interest rate from 0% to 100%.';
    else if (isNaN(startYear) || startYear % 1 !== 0 || startYear < 1900 || startYear > 2200) msg = 'Enter the first payment year as a four-digit year.';
    else if (m === 'date') {
      if (isNaN(endYear) || endYear % 1 !== 0 || endYear < 1900 || endYear > 2300) msg = 'Enter the payoff year as a four-digit year.';
      else if ((endYear - startYear) * 12 + endMonth - startMonth < 0) msg = 'The payoff date must be on or after the first payment date.';
      else if ((endYear - startYear) * 12 + endMonth - startMonth >= MAX_YEARS * 12) msg = 'Choose a payoff date less than 100 years after the first payment.';
    } else if (isNaN(pay) || pay <= 0) msg = 'Enter a payment greater than $0.';

    var i = msg ? 0 : periodicRate(rate / 100, compound, perYear);
    var r = null;
    if (!msg && m === 'payment' && pay <= balance * i + 0.005)
      msg = 'That payment does not cover one period’s interest of ' + money.format(balance * i) +
            ', so the balance would never be repaid. Enter a larger payment.';
    if (!msg) {
      if (m === 'date') {
        var span = (endYear - startYear) * 12 + endMonth - startMonth;
        var n = Math.floor(span * perYear / 12 + 1e-9) + 1;
        r = simulate(balance, i, payment(balance, i, n), n + 1);
      } else {
        r = simulate(balance, i, pay, MAX_YEARS * perYear);
        if (r.balance > 0) msg = 'At that payment the balance would take more than 100 years to repay. Enter a larger payment.';
      }
    }
    var error = el('rpError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var count = r.rows.length;
    var dateOf = function (k) { return paymentDate(startYear, startMonth, perYear, k); };
    var name = NAMES[perYear] || 'regular';
    if (m === 'date') {
      setText('rpMainLabel', 'Payment needed (' + name + ')');
      setText('rpMain', money.format(r.rows[0].amount));
      setText('rpSummary', 'Pay ' + money.format(r.rows[0].amount) + ' ' + (perYear === 26 ? 'every two weeks' : name) +
        ' from ' + monthYear(dateOf(1)) + ' to be debt-free by ' + monthYear(dateOf(count)) + '.');
    } else {
      setText('rpMainLabel', 'Debt-free by');
      setText('rpMain', monthYear(dateOf(count)));
      setText('rpSummary', 'Paying ' + money.format(pay) + ' ' + (perYear === 26 ? 'every two weeks' : name) + ' clears the balance in ' +
        count + (count === 1 ? ' payment.' : ' payments.'));
    }
    setText('rpPayoff', monthYear(dateOf(count)));
    setText('rpInterest', money.format(r.totalInterest));
    setText('rpTotal', money.format(r.totalPaid));
    setText('rpCount', String(count));
    setText('rpTime', duration(count * 12 / perYear));
    setText('rpFinal', money.format(r.rows[count - 1].amount));
    last = { rows: r.rows, dateOf: dateOf };
    renderSchedule();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('rpForm');
    if (!form) return;
    var now = new Date(), first = new Date(now.getFullYear(), now.getMonth() + 1, 1);
    el('rpStartMonth').value = String(first.getMonth());
    el('rpStartYear').value = String(first.getFullYear());
    el('rpEndMonth').value = String((first.getMonth() + 11) % 12);
    el('rpEndYear').value = String(first.getFullYear() + (first.getMonth() === 0 ? 4 : 5));
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('rpView').addEventListener('change', renderSchedule);
    update();
  });
})();
